  values ('bhagavad-gita', (select id from public.traditions where slug = 'sanatan-dharma'), (select id from public.scripture_categories where tradition_id = (select id from public.traditions where slug = 'sanatan-dharma') and slug = 'bhagavad-gita'),
    (select id from public.scriptures where slug = 'mahabharata'),
    'Bhagavad Gita', 'भगवद्गीता', 'The song of the Lord', 'The Bhagavad Gita is a dialogue between Arjuna and Krishna, narrated to the blind king Dhritarashtra by Sanjaya. It is the best known of the Gitas and is studied as a text in its own right.', 'It is set at the opening of the Kurukshetra war, when Arjuna, facing relatives and teachers in the opposing army, loses his resolve. It is classed as Smriti. Dating is debated among scholars, so DharmaQuest does not state a single date.', 'Mahabharata, Bhishma Parva',
    'chaptered'::public.structure_kind, 18, 700, 'Eighteen chapters. The traditional count is 700 verses. The recension commonly printed today has 701 numbered verses because chapter 13 opens with an extra verse (13.1), which some recensions omit.', array['Krishna', 'Arjuna', 'Sanjaya', 'Dhritarashtra']::text[], array['Dharma and duty', 'Karma Yoga: action without attachment', 'Jnana (knowledge) and the nature of the Self', 'Bhakti (devotion)', 'The three gunas', 'Renunciation and liberation']::text[], array['The Self is distinct from the body and is not destroyed with it (chapter 2).', 'One has a claim to action but not to its fruits, and detachment is not an excuse for inaction (2.47).', 'Action offered without attachment does not bind (chapters 3–5).', 'The paths of knowledge, action, meditation and devotion are all taught (chapters 6–12).']::text[],
    '{}'::jsonb, 42, 'published'::public.content_status, 'published'::public.content_status)
