-- Chapters: Bhagavad Gita chapters, Ramayana kandas, Mahabharata parvas
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 1, 'chapter-1', 'अर्जुनविषादयोग', 'Arjuna Vishada Yoga', 'Arjuna’s Dejection', 47, 'The opening chapter sets the scene: the armies are drawn up at Kurukshetra and Arjuna is overcome by doubt.', 'Dhritarashtra asks Sanjaya what happened at Kurukshetra. Arjuna asks Krishna, his charioteer, to place the chariot between the two armies. Seeing relatives and teachers on both sides, he becomes despondent and sets down his bow.', 'The teaching begins from a crisis of duty and compassion. Arjuna’s question is what makes the rest of the Gita necessary.', array['Dharma', 'Grief and confusion (moha)', 'Duty and relationship']::text[], '[{"ref":"1.1","topic":"Dhritarashtra’s question to Sanjaya"},{"ref":"1.47","topic":"Arjuna sits down in the chariot, setting aside bow and arrows"}]'::jsonb, 1, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 2, 'chapter-2', 'साङ्ख्ययोग', 'Sankhya Yoga', 'The Yoga of Knowledge', 72, 'This chapter introduces the main themes of the Gita: the Self, duty, and the discipline of action.', 'Arjuna asks Krishna to teach him as a disciple. Krishna speaks of the eternal Self as distinct from the body, then of duty, and then introduces the discipline of action (karma yoga). The chapter closes with a portrait of the person of steady wisdom (sthitaprajna).', 'The Self is not destroyed with the body, and one may act with full commitment while giving up attachment to results.', array['Atman (the Self)', 'Svadharma (one’s own duty)', 'Buddhi yoga / karma yoga', 'Sthitaprajna (steady wisdom)', 'Samatva (equanimity)']::text[], '[{"ref":"2.7","topic":"Arjuna asks Krishna to teach him as a disciple"},{"ref":"2.20","topic":"The Self is neither born nor dies"},{"ref":"2.47","topic":"The claim to action, not to its fruits"},{"ref":"2.48","topic":"Equanimity is called yoga"},{"ref":"2.55","topic":"Giving up desires: the mark of steady wisdom"}]'::jsonb, 2, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 3, 'chapter-3', 'कर्मयोग', 'Karma Yoga', 'The Yoga of Action', 43, 'Arjuna asks why he should act at all if knowledge is held higher.', 'Krishna explains that no one can remain wholly without action, and teaches action done as an offering (yajna) and without attachment. He speaks of the example set by leaders and of desire and anger as obstacles.', 'Action, rightly understood, is a path in itself, and it is done for the sake of the world and not for personal gain.', array['Karma', 'Yajna (action as offering)', 'Lokasangraha (the welfare of the world)', 'Desire (kama) as an obstacle']::text[], '[{"ref":"3.9","topic":"Action done as sacrifice; other action binds"},{"ref":"3.27","topic":"The gunas act, while the ego thinks “I am the doer”"},{"ref":"3.35","topic":"One’s own duty over another’s, even when imperfectly done"}]'::jsonb, 3, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 4, 'chapter-4', 'ज्ञानकर्मसंन्यासयोग', 'Jnana Karma Sannyasa Yoga', 'Knowledge and Renunciation of Action', 42, 'The chapter links knowledge, action and renunciation.', 'Krishna says he taught this yoga in an earlier age, and speaks of his own repeated manifestation. He describes different kinds of sacrifice, the idea of seeing inaction in action, and the purifying power of knowledge.', 'Knowledge and action are not opposed: action done with knowledge is freed from binding effect.', array['Avatara', 'Akarma (inaction within action)', 'Jnana-yajna', 'Guru and disciple']::text[], '[{"ref":"4.7","topic":"Whenever dharma declines"},{"ref":"4.8","topic":"The purpose of the divine manifestation"},{"ref":"4.18","topic":"Seeing inaction in action and action in inaction"},{"ref":"4.38","topic":"Nothing here is as purifying as knowledge"}]'::jsonb, 4, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 5, 'chapter-5', 'कर्मसंन्यासयोग', 'Karma Sannyasa Yoga', 'Renunciation of Action', 29, 'Arjuna asks which is better: renouncing action or practising karma yoga.', 'Krishna answers that both lead to the highest, and that karma yoga is the better of the two. He describes the person who acts without attachment, equal vision, and the peace of one who has mastered the senses.', 'Inner renunciation matters more than outward abandonment of action.', array['Sannyasa', 'Karma yoga', 'Sama-darshana (equal vision)', 'Peace (shanti)']::text[], '[{"ref":"5.10","topic":"Acting without attachment, like a lotus leaf untouched by water"},{"ref":"5.18","topic":"The wise see with equal vision"}]'::jsonb, 5, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 6, 'chapter-6', 'ध्यानयोग', 'Dhyana Yoga', 'The Yoga of Meditation', 47, 'The chapter on meditation and discipline of the mind.', 'Krishna describes the practice of meditation: a steady seat, moderation, and mastery of the mind. He explains that the restless mind is controlled by practice and detachment, and addresses what becomes of one whose yoga is incomplete.', 'The mind can be either one’s friend or one’s enemy, and it can be trained.', array['Dhyana (meditation)', 'Abhyasa (practice)', 'Vairagya (detachment)', 'Yukta (moderation)']::text[], '[{"ref":"6.5","topic":"Lift yourself by your own self"},{"ref":"6.6","topic":"The self as friend and as enemy"},{"ref":"6.17","topic":"Moderation in food, recreation, work and sleep"},{"ref":"6.35","topic":"The mind is restless and hard to restrain"}]'::jsonb, 6, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 7, 'chapter-7', 'ज्ञानविज्ञानयोग', 'Jnana Vijnana Yoga', 'Knowledge and Realisation', 30, 'Krishna begins to describe his own nature.', 'He speaks of his two natures, the higher and the lower, and of the divine power (maya) made of the three gunas. He describes different kinds of devotees and the rare person who comes to know him after long effort.', 'The world is understood as resting on the divine, and taking refuge is the way across maya.', array['Para and apara prakriti', 'Maya', 'The gunas', 'Kinds of devotees']::text[], '[{"ref":"7.7","topic":"All is strung on Me like gems on a thread"},{"ref":"7.14","topic":"The divine maya of the gunas is hard to cross"},{"ref":"7.19","topic":"After many births, “Vasudeva is all”"}]'::jsonb, 7, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 8, 'chapter-8', 'अक्षरब्रह्मयोग', 'Akshara Brahma Yoga', 'The Imperishable Brahman', 28, 'Arjuna asks a series of questions about Brahman, the Self and action.', 'Krishna answers, and speaks of remembering him at the time of death, the syllable Om, and the paths by which the departed are said to go.', 'A life’s steady remembrance shapes its end.', array['Akshara (imperishable) Brahman', 'Remembrance at death', 'Om']::text[], '[{"ref":"8.5","topic":"Remembering Me at the time of death"},{"ref":"8.13","topic":"Uttering Om, the one-syllable Brahman"}]'::jsonb, 8, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 9, 'chapter-9', 'राजविद्याराजगुह्ययोग', 'Raja Vidya Raja Guhya Yoga', 'Royal Knowledge, Royal Secret', 34, 'Krishna calls this the royal knowledge and royal secret.', 'He says he pervades the universe without being limited by it. He teaches that devotion can be expressed in simple offerings, and that anyone who takes refuge in him with devotion is accepted.', 'Devotion is open to all, and it is the attitude that matters more than the offering.', array['Raja vidya', 'Bhakti', 'Yogakshema']::text[], '[{"ref":"9.22","topic":"For those who think of Me alone, I carry what they lack and preserve what they have"},{"ref":"9.26","topic":"The offering of a leaf, a flower, fruit or water with devotion"},{"ref":"9.34","topic":"Fix your mind on Me"}]'::jsonb, 9, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 10, 'chapter-10', 'विभूतियोग', 'Vibhuti Yoga', 'Divine Glories', 42, 'Krishna describes his manifestations (vibhutis).', 'He names the finest or most essential of each kind of thing as his manifestation. Arjuna praises him and asks for these glories to be described.', 'The divine can be recognised in what is excellent and essential in the world.', array['Vibhuti', 'The source of all']::text[], '[{"ref":"10.8","topic":"I am the source of all; everything proceeds from Me"},{"ref":"10.20","topic":"I am the Self seated in the hearts of all beings"}]'::jsonb, 10, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 11, 'chapter-11', 'विश्वरूपदर्शनयोग', 'Vishvarupa Darshana Yoga', 'Vision of the Universal Form', 55, 'Arjuna asks to see the universal form of Krishna.', 'Krishna grants Arjuna divine sight. Arjuna sees a vast, overwhelming form and is awestruck and afraid. Krishna presents himself as Time. Arjuna asks him to return to his familiar form.', 'Devotion, and not argument or effort alone, is the way to know the divine.', array['Vishvarupa (universal form)', 'Kala (Time)', 'Ananya bhakti (exclusive devotion)']::text[], '[{"ref":"11.12","topic":"The radiance of a thousand suns arising at once"},{"ref":"11.32","topic":"Krishna as Time, the destroyer of worlds"},{"ref":"11.55","topic":"The chapter’s closing summary of the devotee"}]'::jsonb, 11, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 12, 'chapter-12', 'भक्तियोग', 'Bhakti Yoga', 'The Yoga of Devotion', 20, 'Arjuna asks whether devotees who worship a personal form or those who contemplate the unmanifest are better established.', 'Krishna says those who worship him with faith are the best established, and that the path of the unmanifest is harder to follow. He sets out a gradation of practices and describes the qualities of the devotee dear to him.', 'Devotion is cultivated through steady practice, and it shows itself in character.', array['Saguna and nirguna worship', 'Bhakti', 'Abhyasa']::text[], '[{"ref":"12.8","topic":"Fix your mind on Me alone"},{"ref":"12.13","topic":"One who hates no being, friendly and compassionate"},{"ref":"12.15","topic":"One by whom the world is not agitated"}]'::jsonb, 12, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 13, 'chapter-13', 'क्षेत्रक्षेत्रज्ञविभागयोग', 'Kshetra Kshetrajna Vibhaga Yoga', 'The Field and Its Knower', 35, 'Krishna distinguishes the “field” from the “knower of the field”.', 'He describes the body and its constituents as the field, and the Self as its knower. He lists qualities that make up knowledge and speaks of prakriti and purusha and of the Supreme as witness.', 'To know the Self is to distinguish it from the field it observes.', array['Kshetra and kshetrajna', 'Jnana', 'Prakriti and purusha']::text[], '[{"ref":"13.2","topic":"The body is called the field; its knower is the kshetrajna"},{"ref":"13.8","topic":"The beginning of the list of qualities of knowledge"}]'::jsonb, 13, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 14, 'chapter-14', 'गुणत्रयविभागयोग', 'Gunatraya Vibhaga Yoga', 'The Three Gunas', 27, 'The chapter analyses the three gunas of nature.', 'Krishna describes sattva, rajas and tamas, how each binds the embodied self, and how they shape action and rebirth. He describes the person who has gone beyond the gunas.', 'Understanding the gunas is a step towards freedom from their hold.', array['Sattva, rajas, tamas', 'Gunatita (one beyond the gunas)']::text[], '[{"ref":"14.5","topic":"Sattva, rajas and tamas, born of nature, bind the embodied"},{"ref":"14.26","topic":"One who serves Me with unwavering devotion transcends the gunas"}]'::jsonb, 14, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 15, 'chapter-15', 'पुरुषोत्तमयोग', 'Purushottama Yoga', 'The Supreme Person', 20, 'The chapter opens with the image of the ashvattha tree.', 'Krishna describes a tree with roots above and branches below, and the need to cut it with the sword of detachment. He speaks of the individual self as a part of himself, and of the Supreme Person beyond the perishable and the imperishable.', 'Detachment and knowledge lead to the highest reality.', array['Ashvattha tree', 'Kshara and akshara', 'Purushottama']::text[], '[{"ref":"15.1","topic":"The tree with roots above and branches below"},{"ref":"15.7","topic":"The individual self as an eternal portion of Krishna"},{"ref":"15.15","topic":"I am seated in the hearts of all"}]'::jsonb, 15, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
    important_verses = excluded.important_verses, position = excluded.position, status = excluded.status;
insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 16, 'chapter-16', 'दैवासुरसम्पद्विभागयोग', 'Daivasura Sampad Vibhaga Yoga', 'Divine and Demonic Natures', 24, 'The chapter contrasts two kinds of inner endowment.', 'Krishna lists divine qualities and describes the mindset that he calls demonic. He names desire, anger and greed as three gates of ruin, and points to scripture as guidance for action.', 'Character is the ground on which spiritual life stands.', array['Daivi sampad', 'Asuri sampad', 'Shastra as a guide']::text[], '[{"ref":"16.1","topic":"The beginning of the list of divine qualities"},{"ref":"16.21","topic":"Desire, anger and greed as three gates of ruin"}]'::jsonb, 16, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
