insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 17, 'chapter-17', 'श्रद्धात्रयविभागयोग', 'Shraddhatraya Vibhaga Yoga', 'The Three Kinds of Faith', 28, 'Arjuna asks about those who worship with faith but without following scripture.', 'Krishna describes three kinds of faith, and how food, sacrifice, austerity and giving each take sattvic, rajasic or tamasic forms. He closes with the syllables Om Tat Sat.', 'The quality of one’s faith shapes the quality of one’s practice.', array['Shraddha', 'Tapas (of body, speech and mind)', 'Om Tat Sat']::text[], '[{"ref":"17.3","topic":"Each person’s faith accords with their nature"},{"ref":"17.15","topic":"Speech that is truthful, pleasant, beneficial and causes no distress"}]'::jsonb, 17, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
    verse_count = excluded.verse_count, intro = excluded.intro, summary = excluded.summary, message = excluded.message, key_concepts = excluded.key_concepts,
