insert into public.chapters (scripture_id, unit_kind, number, slug, sanskrit_name, name, english_title, verse_count, intro, summary, message, key_concepts, important_verses, position, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'), 'chapter', 18, 'chapter-18', 'मोक्षसंन्यासयोग', 'Moksha Sannyasa Yoga', 'Liberation through Renunciation', 78, 'The longest chapter, which gathers and concludes the teaching.', 'Krishna distinguishes renunciation (sannyasa) from relinquishing the fruits of action (tyaga), analyses action, knowledge and the doer by the three gunas, and speaks of one’s own duty. He ends with the call to take refuge in him. Arjuna declares that his doubt is gone, and Sanjaya concludes.', 'The Gita closes by returning Arjuna to action, now with clarity and a settled resolve.', array['Tyaga and sannyasa', 'Svadharma', 'Sharanagati (taking refuge)']::text[], '[{"ref":"18.46","topic":"Worshipping through one’s own work"},{"ref":"18.66","topic":"“Abandon all dharmas and take refuge in Me alone”. Schools differ on its reading"},{"ref":"18.73","topic":"Arjuna: “My delusion is destroyed”"},{"ref":"18.78","topic":"The final verse of the Gita"}]'::jsonb, 18, 'published')
  on conflict (scripture_id, unit_kind, number) do update set slug = excluded.slug, sanskrit_name = excluded.sanskrit_name, name = excluded.name, english_title = excluded.english_title,
