-- Verses: only verses with a verified source are present. Translations stay absent until a named, licensed translator is added.
insert into public.verses (scripture_id, chapter_id, number, label, position, sanskrit, transliteration, transliteration_scheme, source_id, status)
  values ((select id from public.scriptures where slug = 'bhagavad-gita'),
    (select id from public.chapters where scripture_id = (select id from public.scriptures where slug = 'bhagavad-gita') and unit_kind = 'chapter' and number = 2),
    47, '2.47', 47, array['कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।', 'मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥']::text[], array['karmaṇy evādhikāras te mā phaleṣu kadācana |', 'mā karma-phala-hetur bhūr mā te saṅgo ’stv akarmaṇi ||']::text[], 'IAST', (select id from public.content_sources where slug = 'bg-sanskrit-standard'), 'published')
  on conflict (scripture_id, label) do update set sanskrit = excluded.sanskrit, transliteration = excluded.transliteration,
