insert into public.verse_explanations (verse_id, kind, body, payload, status) values ((select id from public.verses where scripture_id = (select id from public.scriptures where slug = 'bhagavad-gita') and label = '2.47'), 'brief_summary'::public.explanation_kind, 'Krishna explains that we should focus on performing our responsibilities without becoming attached to the results. The teaching also warns against using this idea as an excuse for inaction.', '{"say":"Your claim is to action alone, never to its fruits. Do not let the fruit of action be your motive, and do not be attached to inaction.","why":"It is one of the best-known statements of karma yoga. It appears in Sankhya Yoga, where Krishna turns from the teaching on the Self to the discipline of action.","learn":"Give full effort to the work itself, since outcomes depend on much that is beyond our control, and still keep acting."}'::jsonb, 'published')
  on conflict (verse_id, kind) do update set body = excluded.body, payload = excluded.payload, status = excluded.status;
insert into public.verse_explanations (verse_id, kind, body, payload, status) values ((select id from public.verses where scripture_id = (select id from public.scriptures where slug = 'bhagavad-gita') and label = '2.47'), 'detailed_explanation'::public.explanation_kind, 'Karma: Action. In the Gita’s context, especially action that is one’s duty or responsibility. Adhikara: Right, entitlement or authority. The verse says one’s adhikara is over action, not over results. Phala: Fruit, result or outcome of an action. Sanga: Attachment. The verse names two forms to avoid: motive fixed on the fruit, and attachment to inaction.', '{"terms":[{"term":"Karma","meaning":"Action. In the Gita’s context, especially action that is one’s duty or responsibility."},{"term":"Adhikara","meaning":"Right, entitlement or authority. The verse says one’s adhikara is over action, not over results."},{"term":"Phala","meaning":"Fruit, result or outcome of an action."},{"term":"Sanga","meaning":"Attachment. The verse names two forms to avoid: motive fixed on the fruit, and attachment to inaction."}],"structure":["First half (line 1): your entitlement is to action alone, never to its fruits.","Second half, first part: do not make the fruit of action your motive.","Second half, second part: let there be no attachment to inaction."]}'::jsonb, 'published')
  on conflict (verse_id, kind) do update set body = excluded.body, payload = excluded.payload, status = excluded.status;
insert into public.verse_explanations (verse_id, kind, body, payload, status) values ((select id from public.verses where scripture_id = (select id from public.scriptures where slug = 'bhagavad-gita') and label = '2.47'), 'context'::public.explanation_kind, 'The verse falls in chapter 2. After teaching Arjuna about the eternal Self, Krishna introduces the discipline of action (the chapter itself marks this turn from Sankhya to yoga). The verse comes before the description of equanimity as yoga (2.48) and the portrait of steady wisdom.', '{}'::jsonb, 'published')
  on conflict (verse_id, kind) do update set body = excluded.body, payload = excluded.payload, status = excluded.status;
insert into public.verse_explanations (verse_id, kind, body, payload, status) values ((select id from public.verses where scripture_id = (select id from public.scriptures where slug = 'bhagavad-gita') and label = '2.47'), 'practical_application'::public.explanation_kind, 'The verse can be read as a guide to working with commitment while holding results lightly. Its last line is a guard against reading it as permission to disengage.', '{}'::jsonb, 'published')
  on conflict (verse_id, kind) do update set body = excluded.body, payload = excluded.payload, status = excluded.status;

