-- Darshanas (six classical schools) and Vedanta sub-schools (a separate kind with a parent)
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('nyaya', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 1, 'Nyaya', 'न्याय', 'Logic, reasoning and valid knowledge', 'How do we know what is true?', 'Nyaya is the school of logic and epistemology. It studies the means by which reliable knowledge is gained and how to reason and debate soundly.', 'Nyaya Sutras', 'Traditionally attributed to Gautama (Akshapada).', array['Nyaya later combined with Vaisheshika, and the two are often studied together.']::text[], 1, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('vaisheshika', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 2, 'Vaisheshika', 'वैशेषिक', 'Categories of reality', 'What makes up the world?', 'Vaisheshika analyses reality into fundamental categories. In its classical form it includes an atomistic account of matter, which should be understood in its own philosophical context and not as modern physics.', 'Vaisheshika Sutras', 'Traditionally attributed to Kanada.', array[]::text[], 2, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('samkhya', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 3, 'Samkhya', 'सांख्य', 'Consciousness, nature and liberation', 'What is consciousness, and how is it different from nature?', 'Samkhya distinguishes conscious awareness from the material world and describes how the world evolves. Liberation is understood as discriminating knowledge of this difference.', 'Samkhya Karika', 'By Ishvarakrishna. The classical Samkhya Karika is the best-known surviving text of the school.', array[]::text[], 3, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('yoga', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 4, 'Yoga', 'योग', 'Discipline of the mind and inner clarity', 'How can we discipline the mind and attain inner clarity?', 'The Yoga Darshana presents a systematic practice for steadying the mind. It shares much of its framework with Samkhya, and adds a practical discipline and the notion of Ishvara.', 'Yoga Sutras', 'Traditionally attributed to Patanjali.', array['“Yoga” is also used for many other paths (such as Karma Yoga and Bhakti Yoga in the Bhagavad Gita), which differ from the Yoga Darshana.']::text[], 4, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('purva-mimamsa', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 5, 'Purva Mimamsa', 'पूर्वमीमांसा', 'Vedic interpretation, Dharma and ritual duty', 'How do we understand Dharma and our duties?', 'Purva Mimamsa is the school of Vedic interpretation. It develops rules for understanding the Vedic injunctions and treats Dharma as duty enjoined by the Veda, with extensive reflection on language and meaning.', 'Mimamsa Sutras', 'Traditionally attributed to Jaimini.', array['Called “Purva” (earlier) Mimamsa in contrast to Uttara (later) Mimamsa, a name for Vedanta.']::text[], 5, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, number, name, sanskrit_name, focus, core_question, summary, foundational_text, foundational_attribution, notes, position, status, detail_status)
  values ('vedanta', (select id from public.traditions where slug = 'sanatan-dharma'), 'darshana', null, 6, 'Vedanta', 'वेदान्त', 'Brahman, Atman and liberation', 'What is the ultimate nature of reality and the Self?', 'Vedanta draws on the Upanishads, the Brahma Sutras and the Bhagavad Gita. Its schools agree on the importance of knowing Brahman and the Self but differ, sometimes sharply, on how they relate.', 'Brahma Sutras', 'Traditionally attributed to Badarayana.', array['The Vedanta traditions below are sub-schools within Vedanta. They are not separate Darshanas.']::text[], 6, 'published', 'under_review'::public.content_status)
  on conflict (slug) do update set name = excluded.name, sanskrit_name = excluded.sanskrit_name, focus = excluded.focus, core_question = excluded.core_question, summary = excluded.summary,
    foundational_text = excluded.foundational_text, foundational_attribution = excluded.foundational_attribution, notes = excluded.notes, position = excluded.position,
    status = excluded.status, detail_status = excluded.detail_status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('advaita', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Advaita Vedanta', 'Non-dual: the individual Self (jiva) is ultimately identical with Brahman. Apparent difference is attributed to ignorance (avidya).', array['Associated with Adi Shankara.']::text[], 1, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('vishishtadvaita', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Vishishtadvaita', 'Qualified non-dualism: Brahman is one, and souls and matter are real and inseparable from Brahman, forming its “body”.', array['Associated with Ramanuja.']::text[], 2, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('dvaita', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Dvaita', 'Dualism: God (Vishnu) and individual souls are eternally distinct, and matter is distinct as well. The tradition lists five differences: God–soul, God–matter, soul–soul, soul–matter and matter–matter.', array['Associated with Madhvacharya.']::text[], 3, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('shuddhadvaita', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Shuddhadvaita', 'Pure non-dualism: Brahman alone is real. The world and souls are real manifestations of Brahman, and are not products of illusion.', array['Associated with Vallabhacharya.']::text[], 4, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('dvaitadvaita', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Dvaitadvaita', 'Difference and non-difference are both real: souls and the world are different from Brahman in some respects and non-different in others.', array['Associated with Nimbarkacharya.']::text[], 5, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
insert into public.darshanas (slug, tradition_id, kind, parent_id, name, summary, notes, position, status, detail_status)
  values ('achintya-bhedabheda', (select id from public.traditions where slug = 'sanatan-dharma'), 'sub_school', (select id from public.darshanas where slug = 'vedanta'), 'Achintya Bhedabheda', 'Inconceivable (achintya) difference and non-difference: souls and the world are both different from and one with God, in a relation that reason cannot fully grasp.', array['Associated with Chaitanya tradition.']::text[], 6, 'published', 'under_review')
  on conflict (slug) do update set name = excluded.name, summary = excluded.summary, notes = excluded.notes, position = excluded.position, status = excluded.status;
