insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'reality'), 'Realist. The world and its many distinct entities are real and can be known. Nyaya analyses sixteen topics (padarthas), beginning with the means of knowledge (pramana) and the objects of knowledge (prameya).', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'self'), 'The Self (atman) is a distinct, eternal substance, the bearer of knowledge, desire and effort. Consciousness is treated as a quality of the Self and not as its essence.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'liberation'), 'Apavarga: the final end of suffering, reached through right knowledge of the objects of knowledge, including the Self.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'knowledge'), 'Four pramanas: perception (pratyaksha), inference (anumana), comparison (upamana) and reliable testimony (shabda).', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'texts'), 'The Nyaya Sutras (attributed to Gautama, also called Akshapada); Vatsyayana’s commentary; later Navya-Nyaya works such as Gangesha’s Tattvachintamani.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
