  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'nyaya'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'distinct'), 'The school most devoted to the method of reasoning and debate. Its logic and theory of knowledge were drawn on by many other schools.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'vaisheshika'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'reality'), 'Realist pluralism. Reality is analysed into categories (padarthas): substance, quality, action, universal, particularity and inherence. Later authors add absence (abhava). Its atomism concerns the structure of matter in its own philosophical framework.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
insert into public.comparison_cells (darshana_id, dimension_id, body, source_id, status)
  values ((select id from public.darshanas where slug = 'vaisheshika'), (select id from public.comparison_dimensions where set_kind = 'darshana'::public.darshana_kind and slug = 'self'), 'The Self is one of nine substances (earth, water, fire, air, ether, time, space, self and mind): an eternal substance, distinct from the mind and body.', (select id from public.content_sources where slug = 'dharmaquest-editorial'), 'published')
  on conflict (darshana_id, dimension_id) do update set body = excluded.body, source_id = excluded.source_id, status = excluded.status;
