-- Lessons and quizzes
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-overview', 'The Bhagavad Gita: an overview', 'beginner'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Who speaks, where it is set, how the text is organised and what it teaches.', '[{"heading":"What it is","paragraphs":["The Bhagavad Gita is a dialogue between Arjuna and Krishna, narrated to the blind king Dhritarashtra by Sanjaya. It is the best known of the Gitas and is studied as a text in its own right.","It is set at the opening of the Kurukshetra war, when Arjuna, facing relatives and teachers in the opposing army, loses his resolve. It is classed as Smriti. Dating is debated among scholars, so DharmaQuest does not state a single date."]},{"heading":"Structure","paragraphs":["Eighteen chapters. The traditional count is 700 verses. The recension commonly printed today has 701 numbered verses because chapter 13 opens with an extra verse (13.1), which some recensions omit."]},{"heading":"Main teachings","bullets":["The Self is distinct from the body and is not destroyed with it (chapter 2).","One has a claim to action but not to its fruits, and detachment is not an excuse for inaction (2.47).","Action offered without attachment does not bind (chapters 3–5).","The paths of knowledge, action, meditation and devotion are all taught (chapters 6–12)."]},{"heading":"Themes","bullets":["Dharma and duty","Karma Yoga: action without attachment","Jnana (knowledge) and the nature of the Self","Bhakti (devotion)","The three gunas","Renunciation and liberation"]}]'::jsonb, '[{"label":"Bhagavad Gita and its chapters","href":"/gita/bhagavad-gita"},{"label":"The Gita Library","href":"/gita"}]'::jsonb, 4, 1, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch1', 'Bhagavad Gita chapter 1: Arjuna’s Dejection', 'beginner'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The opening chapter sets the scene: the armies are drawn up at Kurukshetra and Arjuna is overcome by doubt.', '[{"heading":"What happens in this chapter","paragraphs":["Dhritarashtra asks Sanjaya what happened at Kurukshetra. Arjuna asks Krishna, his charioteer, to place the chariot between the two armies. Seeing relatives and teachers on both sides, he becomes despondent and sets down his bow."]},{"heading":"Main message","paragraphs":["The teaching begins from a crisis of duty and compassion. Arjuna’s question is what makes the rest of the Gita necessary."]},{"heading":"Key concepts","bullets":["Dharma","Grief and confusion (moha)","Duty and relationship"]},{"heading":"Important verses","bullets":["Gita 1.1: Dhritarashtra’s question to Sanjaya","Gita 1.47: Arjuna sits down in the chariot, setting aside bow and arrows"]}]'::jsonb, '[{"label":"Chapter 1 study page","href":"/gita/bhagavad-gita/1"}]'::jsonb, 3, 2, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch2', 'Bhagavad Gita chapter 2: The Yoga of Knowledge', 'beginner'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'This chapter introduces the main themes of the Gita: the Self, duty, and the discipline of action.', '[{"heading":"What happens in this chapter","paragraphs":["Arjuna asks Krishna to teach him as a disciple. Krishna speaks of the eternal Self as distinct from the body, then of duty, and then introduces the discipline of action (karma yoga). The chapter closes with a portrait of the person of steady wisdom (sthitaprajna)."]},{"heading":"Main message","paragraphs":["The Self is not destroyed with the body, and one may act with full commitment while giving up attachment to results."]},{"heading":"Key concepts","bullets":["Atman (the Self)","Svadharma (one’s own duty)","Buddhi yoga / karma yoga","Sthitaprajna (steady wisdom)","Samatva (equanimity)"]},{"heading":"Important verses","bullets":["Gita 2.7: Arjuna asks Krishna to teach him as a disciple","Gita 2.20: The Self is neither born nor dies","Gita 2.47: The claim to action, not to its fruits","Gita 2.48: Equanimity is called yoga","Gita 2.55: Giving up desires: the mark of steady wisdom"]}]'::jsonb, '[{"label":"Chapter 2 study page","href":"/gita/bhagavad-gita/2"}]'::jsonb, 3, 3, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('verse-2-47', 'Bhagavad Gita 2.47: the claim to action', 'beginner'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'One verse, studied closely: what it says, what its key words mean and how to read it.', '[{"heading":"What is being said?","paragraphs":["Your claim is to action alone, never to its fruits. Do not let the fruit of action be your motive, and do not be attached to inaction."]},{"heading":"What does it mean?","paragraphs":["Krishna explains that we should focus on performing our responsibilities without becoming attached to the results. The teaching also warns against using this idea as an excuse for inaction."]},{"heading":"Why is it important?","paragraphs":["It is one of the best-known statements of karma yoga. It appears in Sankhya Yoga, where Krishna turns from the teaching on the Self to the discipline of action."]},{"heading":"Key terms","bullets":["Karma: Action. In the Gita’s context, especially action that is one’s duty or responsibility.","Adhikara: Right, entitlement or authority. The verse says one’s adhikara is over action, not over results.","Phala: Fruit, result or outcome of an action.","Sanga: Attachment. The verse names two forms to avoid: motive fixed on the fruit, and attachment to inaction."]},{"heading":"What can we learn?","paragraphs":["Give full effort to the work itself, since outcomes depend on much that is beyond our control, and still keep acting."]}]'::jsonb, '[{"label":"Full verse page with word-by-word study","href":"/gita/bhagavad-gita/2/47"}]'::jsonb, 4, 4, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch3', 'Bhagavad Gita chapter 3: The Yoga of Action', 'beginner'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks why he should act at all if knowledge is held higher.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna explains that no one can remain wholly without action, and teaches action done as an offering (yajna) and without attachment. He speaks of the example set by leaders and of desire and anger as obstacles."]},{"heading":"Main message","paragraphs":["Action, rightly understood, is a path in itself, and it is done for the sake of the world and not for personal gain."]},{"heading":"Key concepts","bullets":["Karma","Yajna (action as offering)","Lokasangraha (the welfare of the world)","Desire (kama) as an obstacle"]},{"heading":"Important verses","bullets":["Gita 3.9: Action done as sacrifice; other action binds","Gita 3.27: The gunas act, while the ego thinks “I am the doer”","Gita 3.35: One’s own duty over another’s, even when imperfectly done"]}]'::jsonb, '[{"label":"Chapter 3 study page","href":"/gita/bhagavad-gita/3"}]'::jsonb, 3, 5, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('ramayana', 'Ramayana', 'beginner'::public.level_kind, 'Ramayana', (select id from public.scriptures where slug = 'ramayana'), 'The journey of Rama, its seven Kandas and its retellings.', '[{"heading":"Overview","paragraphs":["The Ramayana is one of the two great Itihasa. The Sanskrit epic is traditionally attributed to the sage Valmiki. It tells the story of Rama, Sita and Lakshmana, and explores duty, devotion, kingship and relationships.","The story has been retold in many languages and traditions, which differ in emphasis and detail."]},{"heading":"The seven Kandas (books)","bullets":["Bala Kanda: Childhood and early life of Rama.","Ayodhya Kanda: Events in Ayodhya and Rama’s exile.","Aranya Kanda: The forest years.","Kishkindha Kanda: The alliance with Sugriva and the Vanaras.","Sundara Kanda: Hanuman’s journey to Lanka.","Yuddha Kanda: The war in Lanka.","Uttara Kanda: The later events. Some scholars and traditions treat this book as a later addition."]},{"heading":"Notes on sources","bullets":["Notable retellings include Kamban’s Tamil Iramavataram and Tulsidas’s Awadhi Ramcharitmanas.","Major characters: Rama, Sita, Lakshmana, Bharata, Hanuman, Ravana, Dasharatha."]}]'::jsonb, '[{"label":"Ramayana","href":"/scriptures/ramayana"}]'::jsonb, 3, 6, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('vedas', 'The Vedas', 'beginner'::public.level_kind, 'The Vedas', null, 'The oldest layer of the Vedic corpus and its four layers.', '[{"heading":"Overview","paragraphs":["The Vedas are the oldest layer of the Vedic corpus and are classed in the tradition as Shruti — “that which is heard”. Four Vedas are traditionally recognised: the Rigveda, Samaveda, Yajurveda and Atharvaveda.","Each Veda is traditionally understood to have four layers: the Samhitas (collections of hymns and formulae), the Brahmanas (ritual explanation), the Aranyakas (forest texts) and the Upanishads (philosophical inquiry)."]},{"heading":"The four Vedas","bullets":["Rigveda: A collection of hymns (rik), traditionally recited by the Hotri priest.","Samaveda: Hymns set to melody (saman), largely drawn from the Rigvedic hymns.","Yajurveda: Sacrificial formulae (yajus) for ritual performance; transmitted in Shukla and Krishna recensions.","Atharvaveda: Hymns and formulae covering a wide range of themes, including everyday life and philosophical speculation."]},{"heading":"Notes on sources","bullets":["Dating of the Vedic texts is debated among scholars; DharmaQuest does not state a single date."]}]'::jsonb, '[{"label":"The Vedas","href":"/scriptures/vedas"}]'::jsonb, 3, 7, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('upanishads', 'The Upanishads', 'intermediate'::public.level_kind, 'The Upanishads', null, 'Thirteen principal Upanishads and what each explores.', '[{"heading":"Overview","paragraphs":["The Upanishads are philosophical texts that form the concluding portion of the Vedic corpus, which is why they are also called Vedanta. They explore the nature of the Self (Atman), ultimate reality (Brahman), consciousness and liberation (Moksha).","The thirteen below are an initial learning collection of principal Upanishads. The first ten are those commented on by Adi Shankara; Shvetashvatara, Kaushitaki and Maitri are commonly added. This is not an exhaustive list of all Upanishads."]},{"heading":"Thirteen principal Upanishads","bullets":["Isha (Shukla Yajurveda): The pervading presence of the Lord; the relationship between action and knowledge.","Kena (Samaveda): Inquiry into the power behind the mind and senses.","Katha (Krishna Yajurveda): The dialogue of Nachiketa and Yama on death and the Self.","Prashna (Atharvaveda): Six questions put to the sage Pippalada.","Mundaka (Atharvaveda): The distinction between higher and lower knowledge.","Mandukya (Atharvaveda): The syllable Om and the states of consciousness. Associated with the Mahavakya “ayam ātmā brahma”.","Taittiriya (Krishna Yajurveda): The five sheaths (koshas) of the Self and the nature of bliss.","Aitareya (Rigveda): Creation and consciousness. Associated with the Mahavakya “prajñānam brahma”.","Chandogya (Samaveda): Includes the teaching of Uddalaka to Shvetaketu. Associated with the Mahavakya “tat tvam asi”.","Brihadaranyaka (Shukla Yajurveda): Includes the teachings of Yajnavalkya. Associated with the Mahavakya “aham brahmāsmi”.","Shvetashvatara (Krishna Yajurveda): Reflections on God, the individual soul and nature.","Kaushitaki (Rigveda): Teachings on life-force (prana) and the Self.","Maitri (Krishna Yajurveda): Teachings on the Self and the mind."]},{"heading":"Notes on sources","bullets":["The tag on each entry is its traditional Vedic affiliation. Interpretations of each Upanishad differ between Vedanta schools."]}]'::jsonb, '[{"label":"The Upanishads","href":"/scriptures/upanishads"}]'::jsonb, 4, 8, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('mahabharata', 'Mahabharata', 'intermediate'::public.level_kind, 'Mahabharata', (select id from public.scriptures where slug = 'mahabharata'), 'The great Itihasa, its eighteen Parvas and its link to the Gita.', '[{"heading":"Overview","paragraphs":["The Mahabharata is the other great Itihasa, traditionally attributed to Vyasa. It centres on the conflict between the Pandavas and the Kauravas, and contains a vast range of narrative, ethical and philosophical material, including the Bhagavad Gita.","It is known for placing characters in genuine dilemmas of Dharma, where no option is simple."]},{"heading":"The eighteen Parvas (books)","bullets":["Adi Parva","Sabha Parva","Vana Parva","Virata Parva","Udyoga Parva","Bhishma Parva: Contains the Bhagavad Gita.","Drona Parva","Karna Parva","Shalya Parva","Sauptika Parva","Stri Parva","Shanti Parva","Anushasana Parva","Ashvamedhika Parva","Ashramavasika Parva","Mausala Parva","Mahaprasthanika Parva","Svargarohana Parva"]}]'::jsonb, '[{"label":"Mahabharata","href":"/scriptures/mahabharata"}]'::jsonb, 3, 9, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-samkhya', 'Samkhya Darshana', 'intermediate'::public.level_kind, 'Darshanas', null, 'Core question: “What is consciousness, and how is it different from nature?”', '[{"heading":"Overview","paragraphs":["Samkhya distinguishes conscious awareness from the material world and describes how the world evolves. Liberation is understood as discriminating knowledge of this difference."]},{"heading":"Key concepts","bullets":["Purusha: Conscious witness, pure awareness.","Prakriti: Primal nature, the source of the material world.","Gunas: Three strands of nature: sattva, rajas and tamas.","Tattvas: The principles of reality; the classical list has twenty-five."]},{"heading":"How it answers the big questions","bullets":["Dualism of two ultimate principles: purusha (conscious, inactive) and prakriti (insentient primal nature made of the three gunas). The world evolves from prakriti in stages. The classical list has twenty-five principles.","Purusha is pure consciousness: a witness, not an agent. Classical Samkhya holds that there are many purushas, each distinct.","Kaivalya: the isolation of purusha from prakriti, reached through discriminating knowledge of their difference.","Three pramanas: perception, inference and reliable testimony."]},{"heading":"Texts","paragraphs":["The Samkhya Karika of Ishvarakrishna; Vachaspati Mishra’s Tattva-Kaumudi; the later Samkhya-Pravachana-Sutra, with Vijnanabhikshu’s commentary."]},{"heading":"Relation to other schools","paragraphs":["Yoga shares Samkhya’s framework of purusha and prakriti.","Vedanta texts engage critically with Samkhya’s view of nature as the source of the world."]}]'::jsonb, '[{"label":"Samkhya page","href":"/darshanas/samkhya"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 10, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-yoga', 'Yoga Darshana', 'intermediate'::public.level_kind, 'Darshanas', null, 'Core question: “How can we discipline the mind and attain inner clarity?”', '[{"heading":"Overview","paragraphs":["The Yoga Darshana presents a systematic practice for steadying the mind. It shares much of its framework with Samkhya, and adds a practical discipline and the notion of Ishvara."]},{"heading":"Key concepts","bullets":["Chitta vritti nirodha: The stilling of the fluctuations of the mind, as defined in the Yoga Sutras.","Ashtanga: The eight limbs: yama, niyama, asana, pranayama, pratyahara, dharana, dhyana, samadhi.","Samadhi: Absorbed, concentrated awareness."]},{"heading":"How it answers the big questions","bullets":["Shares Samkhya’s framework of purusha and prakriti and adds Ishvara, a special purusha untouched by affliction and karma. Its emphasis is on practice more than on metaphysics.","Purusha is pure awareness, distinct from the mind (chitta). Suffering is traced to confusing the two.","Kaivalya: the stilling of the mind’s fluctuations (chitta-vritti-nirodha), with awareness abiding in its own nature. Samadhi is the culminating practice.","Three pramanas, as listed in the Yoga Sutras: perception, inference and testimony (agama)."]},{"heading":"Texts","paragraphs":["The Yoga Sutras (attributed to Patanjali); Vyasa’s Bhashya; Vachaspati Mishra’s Tattva-Vaisharadi."]},{"heading":"Relation to other schools","paragraphs":["Shares Samkhya’s metaphysical framework and adds Ishvara and a practical discipline."]}]'::jsonb, '[{"label":"Yoga page","href":"/darshanas/yoga"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 11, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch4', 'Bhagavad Gita chapter 4: Knowledge and Renunciation of Action', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The chapter links knowledge, action and renunciation.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna says he taught this yoga in an earlier age, and speaks of his own repeated manifestation. He describes different kinds of sacrifice, the idea of seeing inaction in action, and the purifying power of knowledge."]},{"heading":"Main message","paragraphs":["Knowledge and action are not opposed: action done with knowledge is freed from binding effect."]},{"heading":"Key concepts","bullets":["Avatara","Akarma (inaction within action)","Jnana-yajna","Guru and disciple"]},{"heading":"Important verses","bullets":["Gita 4.7: Whenever dharma declines","Gita 4.8: The purpose of the divine manifestation","Gita 4.18: Seeing inaction in action and action in inaction","Gita 4.38: Nothing here is as purifying as knowledge"]}]'::jsonb, '[{"label":"Chapter 4 study page","href":"/gita/bhagavad-gita/4"}]'::jsonb, 3, 12, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch5', 'Bhagavad Gita chapter 5: Renunciation of Action', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks which is better: renouncing action or practising karma yoga.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna answers that both lead to the highest, and that karma yoga is the better of the two. He describes the person who acts without attachment, equal vision, and the peace of one who has mastered the senses."]},{"heading":"Main message","paragraphs":["Inner renunciation matters more than outward abandonment of action."]},{"heading":"Key concepts","bullets":["Sannyasa","Karma yoga","Sama-darshana (equal vision)","Peace (shanti)"]},{"heading":"Important verses","bullets":["Gita 5.10: Acting without attachment, like a lotus leaf untouched by water","Gita 5.18: The wise see with equal vision"]}]'::jsonb, '[{"label":"Chapter 5 study page","href":"/gita/bhagavad-gita/5"}]'::jsonb, 3, 13, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch6', 'Bhagavad Gita chapter 6: The Yoga of Meditation', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The chapter on meditation and discipline of the mind.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna describes the practice of meditation: a steady seat, moderation, and mastery of the mind. He explains that the restless mind is controlled by practice and detachment, and addresses what becomes of one whose yoga is incomplete."]},{"heading":"Main message","paragraphs":["The mind can be either one’s friend or one’s enemy, and it can be trained."]},{"heading":"Key concepts","bullets":["Dhyana (meditation)","Abhyasa (practice)","Vairagya (detachment)","Yukta (moderation)"]},{"heading":"Important verses","bullets":["Gita 6.5: Lift yourself by your own self","Gita 6.6: The self as friend and as enemy","Gita 6.17: Moderation in food, recreation, work and sleep","Gita 6.35: The mind is restless and hard to restrain"]}]'::jsonb, '[{"label":"Chapter 6 study page","href":"/gita/bhagavad-gita/6"}]'::jsonb, 3, 14, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
