insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch7', 'Bhagavad Gita chapter 7: Knowledge and Realisation', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Krishna begins to describe his own nature.', '[{"heading":"What happens in this chapter","paragraphs":["He speaks of his two natures, the higher and the lower, and of the divine power (maya) made of the three gunas. He describes different kinds of devotees and the rare person who comes to know him after long effort."]},{"heading":"Main message","paragraphs":["The world is understood as resting on the divine, and taking refuge is the way across maya."]},{"heading":"Key concepts","bullets":["Para and apara prakriti","Maya","The gunas","Kinds of devotees"]},{"heading":"Important verses","bullets":["Gita 7.7: All is strung on Me like gems on a thread","Gita 7.14: The divine maya of the gunas is hard to cross","Gita 7.19: After many births, “Vasudeva is all”"]}]'::jsonb, '[{"label":"Chapter 7 study page","href":"/gita/bhagavad-gita/7"}]'::jsonb, 3, 15, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
