insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch8', 'Bhagavad Gita chapter 8: The Imperishable Brahman', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks a series of questions about Brahman, the Self and action.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna answers, and speaks of remembering him at the time of death, the syllable Om, and the paths by which the departed are said to go."]},{"heading":"Main message","paragraphs":["A life’s steady remembrance shapes its end."]},{"heading":"Key concepts","bullets":["Akshara (imperishable) Brahman","Remembrance at death","Om"]},{"heading":"Important verses","bullets":["Gita 8.5: Remembering Me at the time of death","Gita 8.13: Uttering Om, the one-syllable Brahman"]}]'::jsonb, '[{"label":"Chapter 8 study page","href":"/gita/bhagavad-gita/8"}]'::jsonb, 3, 16, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch9', 'Bhagavad Gita chapter 9: Royal Knowledge, Royal Secret', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Krishna calls this the royal knowledge and royal secret.', '[{"heading":"What happens in this chapter","paragraphs":["He says he pervades the universe without being limited by it. He teaches that devotion can be expressed in simple offerings, and that anyone who takes refuge in him with devotion is accepted."]},{"heading":"Main message","paragraphs":["Devotion is open to all, and it is the attitude that matters more than the offering."]},{"heading":"Key concepts","bullets":["Raja vidya","Bhakti","Yogakshema"]},{"heading":"Important verses","bullets":["Gita 9.22: For those who think of Me alone, I carry what they lack and preserve what they have","Gita 9.26: The offering of a leaf, a flower, fruit or water with devotion","Gita 9.34: Fix your mind on Me"]}]'::jsonb, '[{"label":"Chapter 9 study page","href":"/gita/bhagavad-gita/9"}]'::jsonb, 3, 17, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
