insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch10', 'Bhagavad Gita chapter 10: Divine Glories', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Krishna describes his manifestations (vibhutis).', '[{"heading":"What happens in this chapter","paragraphs":["He names the finest or most essential of each kind of thing as his manifestation. Arjuna praises him and asks for these glories to be described."]},{"heading":"Main message","paragraphs":["The divine can be recognised in what is excellent and essential in the world."]},{"heading":"Key concepts","bullets":["Vibhuti","The source of all"]},{"heading":"Important verses","bullets":["Gita 10.8: I am the source of all; everything proceeds from Me","Gita 10.20: I am the Self seated in the hearts of all beings"]}]'::jsonb, '[{"label":"Chapter 10 study page","href":"/gita/bhagavad-gita/10"}]'::jsonb, 3, 18, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
