insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch11', 'Bhagavad Gita chapter 11: Vision of the Universal Form', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks to see the universal form of Krishna.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna grants Arjuna divine sight. Arjuna sees a vast, overwhelming form and is awestruck and afraid. Krishna presents himself as Time. Arjuna asks him to return to his familiar form."]},{"heading":"Main message","paragraphs":["Devotion, and not argument or effort alone, is the way to know the divine."]},{"heading":"Key concepts","bullets":["Vishvarupa (universal form)","Kala (Time)","Ananya bhakti (exclusive devotion)"]},{"heading":"Important verses","bullets":["Gita 11.12: The radiance of a thousand suns arising at once","Gita 11.32: Krishna as Time, the destroyer of worlds","Gita 11.55: The chapter’s closing summary of the devotee"]}]'::jsonb, '[{"label":"Chapter 11 study page","href":"/gita/bhagavad-gita/11"}]'::jsonb, 3, 19, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
