insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch12', 'Bhagavad Gita chapter 12: The Yoga of Devotion', 'intermediate'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks whether devotees who worship a personal form or those who contemplate the unmanifest are better established.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna says those who worship him with faith are the best established, and that the path of the unmanifest is harder to follow. He sets out a gradation of practices and describes the qualities of the devotee dear to him."]},{"heading":"Main message","paragraphs":["Devotion is cultivated through steady practice, and it shows itself in character."]},{"heading":"Key concepts","bullets":["Saguna and nirguna worship","Bhakti","Abhyasa"]},{"heading":"Important verses","bullets":["Gita 12.8: Fix your mind on Me alone","Gita 12.13: One who hates no being, friendly and compassionate","Gita 12.15: One by whom the world is not agitated"]}]'::jsonb, '[{"label":"Chapter 12 study page","href":"/gita/bhagavad-gita/12"}]'::jsonb, 3, 20, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
