insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-vedanta', 'Vedanta Darshana', 'advanced'::public.level_kind, 'Darshanas', null, 'Core question: “What is the ultimate nature of reality and the Self?”', '[{"heading":"Overview","paragraphs":["Vedanta draws on the Upanishads, the Brahma Sutras and the Bhagavad Gita. Its schools agree on the importance of knowing Brahman and the Self but differ, sometimes sharply, on how they relate."]},{"heading":"Key concepts","bullets":["Brahman: Ultimate reality.","Atman: The Self.","Moksha: Liberation.","Prasthanatraya: The three foundational sources: Upanishads, Brahma Sutras and Bhagavad Gita."]},{"heading":"How it answers the big questions","bullets":["Centres on Brahman as ultimate reality, understood differently by each sub-school. See the Vedanta comparison for how they differ.","The Self (atman) is central. Whether it is identical with, part of, or distinct from Brahman is what separates the sub-schools.","Moksha, understood as knowledge of Brahman. Its nature differs: realisation of identity in Advaita; closeness to God or service of God in the theistic schools.","The Upanishads, Brahma Sutras and Bhagavad Gita (the Prasthanatraya) are the foundational sources, supported by reasoning. Each sub-school reads them through its own line of commentary."]},{"heading":"Texts","paragraphs":["The Brahma Sutras (attributed to Badarayana), the Upanishads and the Bhagavad Gita, with the commentaries of each sub-school’s founders."]},{"heading":"Relation to other schools","paragraphs":["Traditionally called Uttara Mimamsa, in relation to Purva Mimamsa.","Vedanta sub-schools are not separate Darshanas. Compare them side by side."]}]'::jsonb, '[{"label":"Vedanta page","href":"/darshanas/vedanta"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 21, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('vedanta-subschools', 'Vedanta sub-schools', 'advanced'::public.level_kind, 'Darshanas', null, 'Six traditions within Vedanta, and how they differ on Brahman, the Self and the world.', '[{"heading":"A note on terms","paragraphs":["These are traditions within Vedanta. They are not separate Darshanas. They agree that the Upanishads, Brahma Sutras and Bhagavad Gita are central, and they differ on how Brahman, the individual Self and the world relate."]},{"heading":"How each tradition relates Brahman, soul and world","bullets":["Advaita Vedanta: Non-dual: the individual Self (jiva) is ultimately identical with Brahman. Apparent difference is attributed to ignorance (avidya).","Vishishtadvaita: Qualified non-dualism: Brahman is one, and souls and matter are real and inseparable from Brahman, forming its “body”.","Dvaita: Dualism: God (Vishnu) and individual souls are eternally distinct, and matter is distinct as well. The tradition lists five differences: God–soul, God–matter, soul–soul, soul–matter and matter–matter.","Shuddhadvaita: Pure non-dualism: Brahman alone is real. The world and souls are real manifestations of Brahman, and are not products of illusion.","Dvaitadvaita: Difference and non-difference are both real: souls and the world are different from Brahman in some respects and non-different in others.","Achintya Bhedabheda: Inconceivable (achintya) difference and non-difference: souls and the world are both different from and one with God, in a relation that reason cannot fully grasp."]},{"heading":"Founding teachers","bullets":["Advaita Vedanta: Gaudapada and Adi Shankara, followed by later teachers.","Vishishtadvaita: Ramanuja, within the Sri Vaishnava tradition.","Dvaita: Madhvacharya.","Shuddhadvaita: Vallabhacharya.","Dvaitadvaita: Nimbarkacharya.","Achintya Bhedabheda: Chaitanya Mahaprabhu (the inspiration of the tradition), Jiva Goswami, Baladeva Vidyabhushana."]}]'::jsonb, '[{"label":"Compare the Vedanta sub-schools","href":"/darshanas/compare?set=vedanta"}]'::jsonb, 4, 22, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-nyaya', 'Nyaya Darshana', 'advanced'::public.level_kind, 'Darshanas', null, 'Core question: “How do we know what is true?”', '[{"heading":"Overview","paragraphs":["Nyaya is the school of logic and epistemology. It studies the means by which reliable knowledge is gained and how to reason and debate soundly."]},{"heading":"Key concepts","bullets":["Pramana: A valid means of knowledge.","Pratyaksha: Perception.","Anumana: Inference.","Upamana: Comparison.","Shabda: Reliable testimony."]},{"heading":"How it answers the big questions","bullets":["Realist. The world and its many distinct entities are real and can be known. Nyaya analyses sixteen topics (padarthas), beginning with the means of knowledge (pramana) and the objects of knowledge (prameya).","The Self (atman) is a distinct, eternal substance, the bearer of knowledge, desire and effort. Consciousness is treated as a quality of the Self and not as its essence.","Apavarga: the final end of suffering, reached through right knowledge of the objects of knowledge, including the Self.","Four pramanas: perception (pratyaksha), inference (anumana), comparison (upamana) and reliable testimony (shabda)."]},{"heading":"Texts","paragraphs":["The Nyaya Sutras (attributed to Gautama, also called Akshapada); Vatsyayana’s commentary; later Navya-Nyaya works such as Gangesha’s Tattvachintamani."]},{"heading":"Relation to other schools","paragraphs":["Traditionally paired with Vaisheshika. Later Nyaya adopts Vaisheshika’s categories, and the two are often studied together."]}]'::jsonb, '[{"label":"Nyaya page","href":"/darshanas/nyaya"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 23, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-vaisheshika', 'Vaisheshika Darshana', 'advanced'::public.level_kind, 'Darshanas', null, 'Core question: “What makes up the world?”', '[{"heading":"Overview","paragraphs":["Vaisheshika analyses reality into fundamental categories. In its classical form it includes an atomistic account of matter, which should be understood in its own philosophical context and not as modern physics."]},{"heading":"Key concepts","bullets":["Dravya: Substance.","Guna: Quality.","Karma: Action or motion (here, in the sense of physical activity).","Samanya: Universal or generality.","Vishesha: Particularity.","Samavaya: Inherence."]},{"heading":"How it answers the big questions","bullets":["Realist pluralism. Reality is analysed into categories (padarthas): substance, quality, action, universal, particularity and inherence. Later authors add absence (abhava). Its atomism concerns the structure of matter in its own philosophical framework.","The Self is one of nine substances (earth, water, fire, air, ether, time, space, self and mind): an eternal substance, distinct from the mind and body.","Moksha: release from the cycle of birth and death, associated with true knowledge (tattvajnana) of the categories.","Two pramanas in the classical school: perception and inference. Testimony is treated as a kind of inference."]},{"heading":"Texts","paragraphs":["The Vaisheshika Sutras (attributed to Kanada); Prashastapada’s Padarthadharmasangraha."]},{"heading":"Relation to other schools","paragraphs":["Traditionally paired with Nyaya, which shares its realist outlook and came to adopt its categories."]}]'::jsonb, '[{"label":"Vaisheshika page","href":"/darshanas/vaisheshika"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 24, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('darshana-purva-mimamsa', 'Purva Mimamsa Darshana', 'advanced'::public.level_kind, 'Darshanas', null, 'Core question: “How do we understand Dharma and our duties?”', '[{"heading":"Overview","paragraphs":["Purva Mimamsa is the school of Vedic interpretation. It develops rules for understanding the Vedic injunctions and treats Dharma as duty enjoined by the Veda, with extensive reflection on language and meaning."]},{"heading":"Key concepts","bullets":["Dharma: In Mimamsa, duty as enjoined by the Veda.","Vidhi: Injunction.","Shabda: Word and verbal testimony, with a developed theory of meaning."]},{"heading":"How it answers the big questions","bullets":["Realist. The world is real, and the Veda is regarded as authorless (apaurusheya) and self-authenticating. Its central concern is what the Vedic injunctions require.","The Self is an eternal, individual knower and agent that continues after death and receives the results of its actions.","Early Mimamsa centres on dharma and its results (such as heaven) more than on liberation. Later thinkers, including Kumarila and Prabhakara, accept liberation as the end of rebirth.","Prabhakara accepts five pramanas: perception, inference, comparison, testimony and presumption (arthapatti). Kumarila adds a sixth, non-apprehension (anupalabdhi)."]},{"heading":"Texts","paragraphs":["The Mimamsa Sutras (attributed to Jaimini); Shabara’s Bhashya; Kumarila Bhatta’s Shlokavarttika; Prabhakara’s Brihati."]},{"heading":"Relation to other schools","paragraphs":["Purva Mimamsa (“earlier inquiry”) and Vedanta, or Uttara Mimamsa (“later inquiry”), are traditionally seen as two parts of one inquiry into the Veda: ritual action and knowledge of Brahman."]}]'::jsonb, '[{"label":"Purva Mimamsa page","href":"/darshanas/purva-mimamsa"},{"label":"Compare the Darshanas","href":"/darshanas/compare"}]'::jsonb, 4, 25, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
    sections = excluded.sections, read_more = excluded.read_more, minutes = excluded.minutes, position = excluded.position, status = excluded.status;
insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch13', 'Bhagavad Gita chapter 13: The Field and Its Knower', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Krishna distinguishes the “field” from the “knower of the field”.', '[{"heading":"What happens in this chapter","paragraphs":["He describes the body and its constituents as the field, and the Self as its knower. He lists qualities that make up knowledge and speaks of prakriti and purusha and of the Supreme as witness."]},{"heading":"Main message","paragraphs":["To know the Self is to distinguish it from the field it observes."]},{"heading":"Key concepts","bullets":["Kshetra and kshetrajna","Jnana","Prakriti and purusha"]},{"heading":"Important verses","bullets":["Gita 13.2: The body is called the field; its knower is the kshetrajna","Gita 13.8: The beginning of the list of qualities of knowledge"]}]'::jsonb, '[{"label":"Chapter 13 study page","href":"/gita/bhagavad-gita/13"}]'::jsonb, 3, 26, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
