insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch14', 'Bhagavad Gita chapter 14: The Three Gunas', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The chapter analyses the three gunas of nature.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna describes sattva, rajas and tamas, how each binds the embodied self, and how they shape action and rebirth. He describes the person who has gone beyond the gunas."]},{"heading":"Main message","paragraphs":["Understanding the gunas is a step towards freedom from their hold."]},{"heading":"Key concepts","bullets":["Sattva, rajas, tamas","Gunatita (one beyond the gunas)"]},{"heading":"Important verses","bullets":["Gita 14.5: Sattva, rajas and tamas, born of nature, bind the embodied","Gita 14.26: One who serves Me with unwavering devotion transcends the gunas"]}]'::jsonb, '[{"label":"Chapter 14 study page","href":"/gita/bhagavad-gita/14"}]'::jsonb, 3, 27, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
