insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch15', 'Bhagavad Gita chapter 15: The Supreme Person', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The chapter opens with the image of the ashvattha tree.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna describes a tree with roots above and branches below, and the need to cut it with the sword of detachment. He speaks of the individual self as a part of himself, and of the Supreme Person beyond the perishable and the imperishable."]},{"heading":"Main message","paragraphs":["Detachment and knowledge lead to the highest reality."]},{"heading":"Key concepts","bullets":["Ashvattha tree","Kshara and akshara","Purushottama"]},{"heading":"Important verses","bullets":["Gita 15.1: The tree with roots above and branches below","Gita 15.7: The individual self as an eternal portion of Krishna","Gita 15.15: I am seated in the hearts of all"]}]'::jsonb, '[{"label":"Chapter 15 study page","href":"/gita/bhagavad-gita/15"}]'::jsonb, 3, 28, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
