insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch16', 'Bhagavad Gita chapter 16: Divine and Demonic Natures', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The chapter contrasts two kinds of inner endowment.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna lists divine qualities and describes the mindset that he calls demonic. He names desire, anger and greed as three gates of ruin, and points to scripture as guidance for action."]},{"heading":"Main message","paragraphs":["Character is the ground on which spiritual life stands."]},{"heading":"Key concepts","bullets":["Daivi sampad","Asuri sampad","Shastra as a guide"]},{"heading":"Important verses","bullets":["Gita 16.1: The beginning of the list of divine qualities","Gita 16.21: Desire, anger and greed as three gates of ruin"]}]'::jsonb, '[{"label":"Chapter 16 study page","href":"/gita/bhagavad-gita/16"}]'::jsonb, 3, 29, 'published')
