insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch17', 'Bhagavad Gita chapter 17: The Three Kinds of Faith', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'Arjuna asks about those who worship with faith but without following scripture.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna describes three kinds of faith, and how food, sacrifice, austerity and giving each take sattvic, rajasic or tamasic forms. He closes with the syllables Om Tat Sat."]},{"heading":"Main message","paragraphs":["The quality of one’s faith shapes the quality of one’s practice."]},{"heading":"Key concepts","bullets":["Shraddha","Tapas (of body, speech and mind)","Om Tat Sat"]},{"heading":"Important verses","bullets":["Gita 17.3: Each person’s faith accords with their nature","Gita 17.15: Speech that is truthful, pleasant, beneficial and causes no distress"]}]'::jsonb, '[{"label":"Chapter 17 study page","href":"/gita/bhagavad-gita/17"}]'::jsonb, 3, 30, 'published')
  on conflict (slug) do update set title = excluded.title, level = excluded.level, collection = excluded.collection, scripture_id = excluded.scripture_id, summary = excluded.summary,
