insert into public.lessons (slug, title, level, collection, scripture_id, summary, sections, read_more, minutes, position, status)
  values ('gita-ch18', 'Bhagavad Gita chapter 18: Liberation through Renunciation', 'advanced'::public.level_kind, 'Bhagavad Gita', (select id from public.scriptures where slug = 'bhagavad-gita'), 'The longest chapter, which gathers and concludes the teaching.', '[{"heading":"What happens in this chapter","paragraphs":["Krishna distinguishes renunciation (sannyasa) from relinquishing the fruits of action (tyaga), analyses action, knowledge and the doer by the three gunas, and speaks of one’s own duty. He ends with the call to take refuge in him. Arjuna declares that his doubt is gone, and Sanjaya concludes."]},{"heading":"Main message","paragraphs":["The Gita closes by returning Arjuna to action, now with clarity and a settled resolve."]},{"heading":"Key concepts","bullets":["Tyaga and sannyasa","Svadharma","Sharanagati (taking refuge)"]},{"heading":"Important verses","bullets":["Gita 18.46: Worshipping through one’s own work","Gita 18.66: “Abandon all dharmas and take refuge in Me alone”. Schools differ on its reading","Gita 18.73: Arjuna: “My delusion is destroyed”","Gita 18.78: The final verse of the Gita"]}]'::jsonb, '[{"label":"Chapter 18 study page","href":"/gita/bhagavad-gita/18"}]'::jsonb, 3, 31, 'published')
